contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function: caller supplies depositor address and amount
    function test_deposit_preserves_at_least_deposited(address depositor, uint256 amount) public payable {
        // ensure this contract has enough ETH to forward
        require(address(this).balance >= amount, "insufficient funds to forward");

        // perform deposit into C as the depositor by using a call from this contract
        // We simulate depositor by making depositor contract call C; since we cannot change msg.sender,
        // instead we require depositor == address(this) so the deposit originates from this contract.
        // This keeps the setup minimal and verifier-friendly.
        require(depositor == address(this), "depositor must be this contract");

        // Call Deposit on C forwarding amount wei
        c.Deposit{value: amount}();

        // Observe recorded balance for this contract (auto getter balances)
        uint256 recorded = c.balances(address(this));

        // Property: recorded balance should be at least the single deposit amount
        assert(recorded >= amount);
    }

    // allow this contract to receive ETH so the test can forward funds
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmount is the Ether sent to c.Deposit by this test
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // observe prior balance
        uint prior = c.balances(address(this));

        // perform the state-changing call, sending Ether
        c.Deposit{value: depositAmount}();

        // observe new balance
        uint after = c.balances(address(this));

        // general rule: new balance equals prior + deposited amount
        assert(after == prior + depositAmount);
    }

    receive() external payable {}
}

