        // read prior recorded balance for this test contract's address via public getter
        uint256 before = c.balances(address(this));

        // perform the deposit of v wei
        c.Deposit{value: v}();

        // observe recorded balance after deposit via public getter
        uint256 after = c.balances(address(this));

        // General rule: after a Deposit of v, the recorded balance for the depositor must be >= max(before, v)
