pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz params: depositor (who calls Deposit), depositorInitial (initial balance to set up),
    // depositAmt (value sent in Deposit), collector (who may call Collect), collectAmt
    function testFuzz_property(address depositor, uint256 depositorInitial, uint256 depositAmt, address collector, uint256 collectAmt) public {
        // keep addresses non-zero to be realistic
        depositor = depositor == address(0) ? address(1) : depositor;
        collector = collector == address(0) ? address(2) : collector;

        // bound amounts to sensible ranges but wide
        depositorInitial = bound(depositorInitial, 0, 1 ether);
        depositAmt = bound(depositAmt, 1, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);

        // Set MinSum to 0 to allow Collect when balance>=0 (no restriction)
        // Must call SetMinSum before Initialized
        vm.prank(address(this));
        c.SetMinSum(0);
        c.Initialized();

        // Give depositor an initial balance by sending via Deposit: we simulate an initial deposit
        vm.deal(depositor, depositorInitial + depositAmt + 1 ether);

        // First, have depositor make an initial deposit equal to depositorInitial
        vm.prank(depositor);
        if (depositorInitial > 0) {
            c.Deposit{value: depositorInitial}();
        }

        // Record balance of some key k before making the next deposit. We'll use collector as the key k to observe
        address k = collector;
        uint256 before = c.balances(k);

        // Now have depositor make the fuzzed deposit of depositAmt
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // Now perform Collect from collector (may be same or different address)
        // Ensure collector has enough ETH to receive funds if Collect sends out value
        vm.deal(collector, 1 ether);
        bool ok;
        vm.prank(collector);
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): For the correct contract, a Deposit by `depositor` must not overwrite balances of other keys.
        // We assert that the balance at key k after the operations is >= before (Deposits and Collects should never make unrelated account balances smaller in the reference contract's logic),
        // but to be robust we assert equality for the reference: balance at k remains equal to before unless k==depositor and depositor made deposits/collects that affect it.
        // To make this a universal property that the reference satisfies for all inputs, we pick k that may differ from depositor; when k != depositor, the balance must be unchanged.

        if (k != depositor) {
            // This is the single required assertTrue observing c's public state
            assertTrue(c.balances(k) == before);
        } else {
            // when k == depositor we cannot assert unchanged; instead assert that balance is at least zero (always true) to keep the single assertion requirement,
            // but to ensure the test is distinguishing, the fuzzer will explore cases where k != depositor and thus trigger the above check.
            assertTrue(c.balances(k) >= 0);
        }
    }
}

