pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: two depositor addresses and two deposit amounts and a collect amount
    function testFuzz_property(address depositorA, address depositorB, uint256 depositA, uint256 depositB, uint256 collectAmt) public {
        // restrict to non-zero distinct addresses to avoid trivialities
        vm.assume(depositorA != address(0));
        vm.assume(depositorB != address(0));
        vm.assume(depositorA != depositorB);

        // bound deposits to reasonable non-zero values that fit in contract balance
        depositA = bound(depositA, 1, 1 ether);
        depositB = bound(depositB, 1, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);

        // Fund the EOAs so they can send value
        vm.deal(depositorA, depositA + 1 ether);
        vm.deal(depositorB, depositB + 1 ether);

        // depositorA makes a deposit
        vm.prank(depositorA);
        c.Deposit{value: depositA}();

        // depositorB makes a deposit
        vm.prank(depositorB);
        c.Deposit{value: depositB}();

        // record depositorB's balance in the contract before any collect
        uint256 beforeB = c.balances(depositorB);

        // Now have depositorA attempt to collect 'collectAmt'
        // Use try/catch to allow both success and revert without failing the test harness
        bool ok;
        vm.prank(depositorA);
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: in the correct contract Deposit increments balances, so other addresses' stored balances cannot decrease as a result of someone else's Collect call.
        // We assert that depositorB's recorded balance did not decrease after depositorA's Collect.
        // This holds for the reference contract for all admissible inputs, but the mutant that overwrites balances on Deposit can cause depositorB's stored value to change (decrease) for some fuzz inputs.
        uint256 afterB = c.balances(depositorB);
        assertTrue(afterB >= beforeB);
    }
}

