        collectAmt = bound(collectAmt, 0, 1 ether);

        // Fund the depositors
        vm.deal(a, depositA);
        vm.deal(b, depositB + collectAmt); // ensure b can also cover potential collect if needed

        // a deposits
        vm.prank(a);
        c.Deposit{value: depositA}();

        // b deposits
        vm.prank(b);
        c.Deposit{value: depositB}();

