pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters:
    // addrA: the depositor who will also call Collect
    // addrB: a second depositor whose stored balance must be preserved by the reference
    // depositA: amount addrA deposits
    // depositB: amount addrB deposits
    // collectAmt: amount addrA attempts to Collect
    function testFuzz_property(address addrA, address addrB, uint256 depositA, uint256 depositB, uint256 collectAmt) public {
        // admissible domain constraints:
        // distinct actors
        vm.assume(addrA != address(0));
        vm.assume(addrB != address(0));
        vm.assume(addrA != addrB);
        // keep deposits nonzero to be meaningful, and bounded to avoid overflow in test harness
        depositA = bound(depositA, 1, 1 ether);
        depositB = bound(depositB, 1, 1 ether);
        // bound collect amount reasonable
        collectAmt = bound(collectAmt, 0, 1 ether);

        // fund both actors so they can send ETH
        vm.deal(addrA, depositA + collectAmt + 1);
        vm.deal(addrB, depositB + 1);

        // addrB deposits depositB
        vm.prank(addrB);
        c.Deposit{value: depositB}();

        // addrA deposits depositA
        vm.prank(addrA);
        c.Deposit{value: depositA}();

        // record B's stored balance before A collects
        uint256 beforeB = c.balances(addrB);

        // make sure A has at least MinSum if collect requires it: set MinSum to 0 via initializer actions
        // (SetMinSum can only be called before Initialized; we don't call Initialized anywhere so it's allowed)
        c.SetMinSum(0);

        // addrA attempts to collect collectAmt; if Collect reverts, ok=false
        bool ok;
        vm.prank(addrA);
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        // After the call, the reference contract guarantees that other addresses' stored balances are unchanged
        // because Deposit only increments sender's own balance and Collect only updates msg.sender's entry.
        // We assert that addrB's stored balance is still the same as before.
        uint256 afterB = c.balances(addrB);

        assertTrue(afterB == beforeB);
    }
}

